new AnimationTimer() {
    private long prev;
    private double lag;
    private static final double DT = 1.0 / 60.0;
    @Override public void handle(long now) {          // one call per rendered frame
        if (prev == 0) { prev = now; return; }
        lag += (now - prev) / 1e9; prev = now;
        if (lag > 0.25) lag = 0.25;                   // clamp
        while (lag >= DT) { world.step(DT); lag -= DT; }
        view.render(lag / DT);                        // interpolate
    }
}.start();

